const geometry=id=>({revision:R.revision,manifestSHA:MANIFEST_SHA,selectionSHA:R.selection.sha256,states:structuredClone(R.scenes[id].states),doorBitOrder:[...R.scenes[id].doorBitOrder],excluded:structuredClone(R.scenes[id].excluded)});
