function direction(id,reverseId,source,target,departure,arrival,face,arrivalFacing){return{id,reverseId,pairId:'NEW_BR_EAST_OPEN__NEW_R_WEST_OPEN',sourceMapId:'world:ship:S9',targetMapId:'world:ship:S9',sourceSceneId:source,targetSceneId:target,departureFoot:departure,departureFacing:face,arrivalFoot:arrival,arrivalFacing,returnDepartureFoot:source==='ship_bridge'?[145,390]:[1390,500],trigger:'EXPLICIT_FRESH_INPUT_SELECTED_REGION_NO_SNAP',condition:'ORIGINAL_COMMITTED_BOSS_RESCUE_EDGE',mode:'development',canonicalInstalled:false,evidence:{status:'ROOT_SELECTED_NEW_CONTACT_WITH_ORIGINAL_ARRIVAL',originalSource:'NEW_PORT_LINK_CONTRACT.json'}}}
