export function createEightSceneRegistry(original){if(stableJSON(original)!==stableJSON(base))throw Error('RESCUE_BASE_REGISTRY');return structuredClone(selected)}
export function verifyEightSceneRegistry(r){try{return stableJSON(r)===stableJSON(selected)}catch{return false}}
