export function rescueAllowsPlacement(id,foot,purpose='movement'){if(!Object.hasOwn(R.scenes,id)||!['movement','warp','spawn','npc','save'].includes(purpose)||!Array.isArray(foot)||foot.length!==2||!foot.every(Number.isInteger))return false;const[x,y]=foot;return x>=0&&x<1536&&y>=0&&y<1024&&!R.scenes[id].excluded.some(([l,t,r,b])=>x>=l&&x<r&&y>=t&&y<b)}
const own=v=>v instanceof ArrayBuffer?new Uint8Array(v.slice(0)):v instanceof Uint8Array?new Uint8Array(v):(()=>{throw Error('RESCUE_BYTE_TYPE')})();
